const state = $('Initialize State').first().json;
const brandData = $input.first().json;

const defaultBrand = { brand_name: "", brand_colors: [], brand_style: "", brand_text: "", logo_url: "", logo_position: "top-right" };

state.brand = brandData && Object.keys(brandData).length > 0
  ? {
      brand_name: brandData.brand_name || "",
      brand_colors: Array.isArray(brandData.brand_colors) ? brandData.brand_colors : [],
      brand_style: brandData.brand_style || "",
      brand_text: brandData.brand_text || "",
      logo_url: brandData.logo_url || "",
      logo_position: brandData.logo_position || "top-right"
    }
  : defaultBrand;

return [{ json: state }];

