const state = { ...$('Merge Image Prompt').last().json };
const response = $input.first().json;

let parsed = {};
try {
  let content = response.output || '{}';
  content = content.replace(/```json|```/g, '').trim();
  parsed = JSON.parse(content);
} catch (e) { parsed = { approved: false, critique: "Failed to parse" }; }

state.image_approved = parsed.approved ?? false;
state.image_critique = parsed.critique ?? "";

if (!state.image_approved) {
  state.image_retries_left = Math.max((state.image_retries_left || 0) - 1, 0);
}

return [{ json: state }];

let state;
try { state = { ...$('Needs New Image?').first().json }; } 
catch (e) { state = { ...$('Initialize State').first().json }; }

// Update text from text loop if it ran
try {
  const textUpdates = $('Update Text State').all();
  if (textUpdates.length > 0) {
    const latestTextState = textUpdates[textUpdates.length - 1].json;
    state.content = latestTextState.content;
  }
} catch (e) {}

// Update image from Cloudinary if it ran
try {
  const upload = $('Upload Image').first().json || {};
  if (upload.secure_url || upload.url) {
    state.image_url = upload.secure_url || upload.url;
  }
} catch (e) {}

const platforms = state.platforms || [];
const finalContent = {};

if (platforms.includes('linkedin')) finalContent.linkedin = state.content.linkedin || "";
if (platforms.includes('facebook')) finalContent.facebook = state.content.facebook || "";
if (platforms.includes('instagram')) finalContent.instagram = state.content.instagram || "";
if (platforms.includes('reddit')) finalContent.reddit = state.content.reddit || "";
if (platforms.includes('twitter')) finalContent.twitter = state.content.twitter || "";

const finalOutput = {
  user_id: state.userId,
  image_url: state.image_url,
  content: finalContent,
  title: state.title,
  tags: state.tags,
  platforms: state.platforms
};

return [{ json: finalOutput }];

